// (src/generated/services/*). Never call fetch/axios/Graph/Azure REST here —
// code apps must access data through Power Platform connectors.

export interface SampleItem {
  id: string;
  name: string;
  status: string;
}

// In-memory only, resets on reload — stands in for a real connector's persistence.
let items: SampleItem[] = [];

export async function listSampleItems(): Promise<SampleItem[]> {
  return items;
}

export async function createSampleItem(name: string): Promise<SampleItem> {
  const item: SampleItem = { id: crypto.randomUUID(), name, status: 'New' };
  items = [...items, item];
  return item;
}
